ArchitectureVisualiser = {
  init: function(app, container) {
    container = container || $(".component[name=ArchitectureVisualiser]");
    const root = container.find(".arch-viz").get(0);
    if (!root || root.dataset.ready === "true") return;
    root.dataset.ready = "true";
    const state = { catalogue: [], definition: null, selected: null, layout: null };
    root._architectureState = state;
    const repo = root.querySelector("[name=repository]");
    const project = root.querySelector("[name=project]");
    const filter = root.querySelector("[name=filter]");
    repo.addEventListener("change", function(){ ArchitectureVisualiser.fillProjects(root); });
    project.addEventListener("change", function(){ ArchitectureVisualiser.selectProject(root); });
    root.querySelector("[name=load]").addEventListener("click", function(){ ArchitectureVisualiser.loadProject(root); });
    filter.addEventListener("input", function(){ ArchitectureVisualiser.render(root); });
    window.addEventListener("resize", function(){ ArchitectureVisualiser.drawLinks(root); });
    fetch("/api/dms/data/architecture/projects.json", { credentials: "same-origin" })
      .then(function(response){ if (!response.ok) throw new Error("Catalogue request returned " + response.status); return response.json(); })
      .then(function(items){
        state.catalogue = items.slice().sort(function(a,b){ return (a.RepoName + a.ProjectName).localeCompare(b.RepoName + b.ProjectName); });
        const repositories = Array.from(new Set(state.catalogue.map(function(item){ return item.RepoName; })));
        repo.innerHTML = repositories.map(function(name){ return "<option>" + ArchitectureVisualiser.escape(name) + "</option>"; }).join("");
        const preferred = repositories.indexOf("ccoder.Core");
        repo.selectedIndex = preferred >= 0 ? preferred : 0;
        ArchitectureVisualiser.fillProjects(root);
      })
      .catch(function(error){ ArchitectureVisualiser.status(root, error.message, true); });
  },
  fillProjects: function(root) {
    const state = root._architectureState;
    const repoName = root.querySelector("[name=repository]").value;
    const project = root.querySelector("[name=project]");
    const items = state.catalogue.filter(function(item){ return item.RepoName === repoName; });
    project.innerHTML = items.map(function(item, index){ return "<option value='" + index + "'>" + ArchitectureVisualiser.escape(item.ProjectName) + "</option>"; }).join("");
    ArchitectureVisualiser.selectProject(root);
    ArchitectureVisualiser.loadProject(root);
  },
  selectProject: function(root) {
    const state = root._architectureState;
    const repoName = root.querySelector("[name=repository]").value;
    const choices = state.catalogue.filter(function(item){ return item.RepoName === repoName; });
    const item = choices[Number(root.querySelector("[name=project]").value) || 0];
    if (!item) return;
    state.selected = item;
    ArchitectureVisualiser.status(root, "Selected " + item.ProjectName + ". Choose Load diagram to render it.", false);
  },
  loadProject: function(root) {
    const state = root._architectureState;
    const repoName = root.querySelector("[name=repository]").value;
    const choices = state.catalogue.filter(function(item){ return item.RepoName === repoName; });
    const item = choices[Number(root.querySelector("[name=project]").value) || 0];
    if (!item) return;
    state.selected = item;
    state.definition = null;
    state.layout = null;
    ArchitectureVisualiser.status(root, "Loading " + item.ProjectName + "…", false);
    const definitionUrl = "/api/dms/data/architecture/definitions/" + encodeURIComponent(item.RepoName) + "/" + encodeURIComponent(item.ProjectName) + ".json";
    fetch(definitionUrl, { credentials: "same-origin" })
      .then(function(response){ if (!response.ok) throw new Error("Definition request returned " + response.status); return response.json(); })
      .then(function(definition){ state.definition = definition; ArchitectureVisualiser.render(root); })
      .catch(function(error){ ArchitectureVisualiser.status(root, error.message, true); });
  },
  buildDependencyForest: function(definition, filterTerm) {
    const classes = (definition.Classes || []).map(function(item){ return Object.assign({ _kind: "Class" }, item); });
    const interfaces = (definition.Interfaces || []).map(function(item){ return Object.assign({ _kind: "Interface" }, item); });
    const declared = classes.concat(interfaces);
    const declaredNames = new Set(declared.map(function(item){ return item.Name; }));
    const externalNames = new Set();
    (definition.Links || []).forEach(function(link){
      if (!declaredNames.has(link.FromType)) externalNames.add(link.FromType);
      if (!declaredNames.has(link.ToType)) externalNames.add(link.ToType);
    });
    const externalDependencies = Array.from(externalNames).map(function(name){
      return { Name: name, StandardElementType: "Dependency", _kind: "External dependency", Methods: [], Properties: [], Interfaces: [] };
    });
    const nodes = declared
      .filter(function(item){ return String(item.StandardElementType || "").toLowerCase() !== "model"; })
      .concat(externalDependencies)
      .sort(function(a,b){ return String(a.Name).localeCompare(String(b.Name)); });
    const byName = new Map(nodes.map(function(item){ return [item.Name, item]; }));
    const dependencies = new Map(nodes.map(function(item){ return [item.Name, []]; }));
    const dependedUpon = new Set();
    (definition.Links || []).forEach(function(link){
      if (!byName.has(link.FromType) || !byName.has(link.ToType) || link.FromType === link.ToType) return;
      const targets = dependencies.get(link.FromType);
      if (targets.indexOf(link.ToType) < 0) targets.push(link.ToType);
      dependedUpon.add(link.ToType);
    });
    dependencies.forEach(function(targets){ targets.sort(function(a,b){ return a.localeCompare(b); }); });

    const covered = new Set();
    function expand(name, path) {
      covered.add(name);
      const nextPath = new Set(path);
      nextPath.add(name);
      const children = (dependencies.get(name) || []).map(function(childName){
        if (nextPath.has(childName)) return { name: childName, item: byName.get(childName), children: [], cycle: true };
        return expand(childName, nextPath);
      });
      return { name: name, item: byName.get(name), children: children, cycle: false };
    }

    const rootNames = nodes.map(function(item){ return item.Name; }).filter(function(name){ return !dependedUpon.has(name); });
    const roots = rootNames.map(function(name){ return expand(name, new Set()); });
    nodes.forEach(function(item){ if (!covered.has(item.Name)) roots.push(expand(item.Name, new Set())); });

    const term = String(filterTerm || "").trim().toLowerCase();
    function prune(node) {
      const children = node.children.map(prune).filter(Boolean);
      if (!term || String(node.name).toLowerCase().indexOf(term) >= 0 || children.length) {
        return { name: node.name, item: node.item, children: children, cycle: node.cycle };
      }
      return null;
    }
    return { nodes: nodes, roots: roots.map(prune).filter(Boolean) };
  },
  getLayerColumn: function(item) {
    const type = String(item && item.StandardElementType || "");
    const inferred = type || String(item && item.Name || "");
    if (type === "AggregationService" || type === "ManagementService") return "Aggregation";
    if (type === "CoordinationService") return "Coordination";
    if (type === "OrchestrationService") return "Orchestration";
    if (type === "ProcessingService") return "Processing";
    if (type === "FoundationService") return "Foundation";
    if (type === "Broker" || /Broker$/.test(inferred)) return "Broker";
    if (type === "Dependency" || /Dependency$/.test(inferred)) return "Dependency";
    return "Exposure";
  },
  getNodePresentation: function(item, analysisItems) {
    const methods = (item.Methods || []).length;
    const properties = (item.Properties || []).length;
    const interfaces = (item.Interfaces || []).map(function(contract){ return contract.FullName || contract.Name; }).filter(Boolean);
    const diagnostics = (analysisItems || []).filter(function(diagnostic){ return diagnostic.Type === item.Name; });
    const parts = [String(item.StandardElementType || item._kind || "Item"), methods + " method" + (methods === 1 ? "" : "s")];
    if (interfaces.length > 0) parts.push(interfaces.length + " interface" + (interfaces.length === 1 ? "" : "s"));
    if (properties > 0) parts.push(properties + " propert" + (properties === 1 ? "y" : "ies"));
    const tooltip = diagnostics.map(function(diagnostic){
      const line = Number(diagnostic.LineNumber) > 0 ? ", line " + diagnostic.LineNumber : "";
      return diagnostic.Code + " (" + diagnostic.Severity + ")" + line + ": " + diagnostic.Description;
    }).join("\n");
    return {
      meta: parts.join(" · "),
      interfaces: interfaces,
      diagnostics: diagnostics,
      tooltip: tooltip,
      isInvalid: diagnostics.length > 0 || properties > 0,
      hasPropertyViolation: properties > 0
    };
  },
  layoutDependencyForest: function(forest) {
    const nodeWidth = 260, nodeHeight = 64, columnGap = 70, rowGap = 20, treeGap = 56, padding = 20, headerHeight = 48;
    const columnNames = ["Exposure", "Aggregation", "Coordination", "Orchestration", "Processing", "Foundation", "Broker", "Dependency"];
    const columns = columnNames.map(function(name, index){ return { name: name, x: padding + index * (nodeWidth + columnGap) }; });
    const columnByName = new Map(columns.map(function(column){ return [column.name, column]; }));
    const positioned = [], edges = [];
    let treeTop = padding + headerHeight, sequence = 0;

    forest.roots.forEach(function(rootNode, treeIndex){
      let nextLeafY = treeTop;
      function place(node, depth, parentId) {
        const id = "tree-" + treeIndex + "-node-" + sequence++;
        const childRecords = node.children.map(function(child){ return place(child, depth + 1, id); });
        let y;
        if (childRecords.length) {
          const firstCentre = childRecords[0].y + nodeHeight / 2;
          const lastCentre = childRecords[childRecords.length - 1].y + nodeHeight / 2;
          y = (firstCentre + lastCentre) / 2 - nodeHeight / 2;
        } else {
          y = nextLeafY;
          nextLeafY += nodeHeight + rowGap;
        }
        const record = {
          id: id,
          name: node.name,
          item: node.item,
          cycle: node.cycle,
          parentId: parentId || null,
          treeIndex: treeIndex,
          depth: depth,
          x: columnByName.get(ArchitectureVisualiser.getLayerColumn(node.item)).x,
          y: y,
          width: nodeWidth,
          height: nodeHeight
        };
        positioned.push(record);
        childRecords.forEach(function(child){ edges.push({ fromId: id, toId: child.id }); });
        return record;
      }
      place(rootNode, 0, null);
      const treeNodes = positioned.filter(function(node){ return node.treeIndex === treeIndex; });
      const nodesByColumn = new Map();
      treeNodes.forEach(function(node){
        const columnNodes = nodesByColumn.get(node.x) || [];
        columnNodes.push(node);
        nodesByColumn.set(node.x, columnNodes);
      });
      nodesByColumn.forEach(function(columnNodes){
        let columnBottom = -Infinity;
        columnNodes.sort(function(a,b){ return a.y - b.y || a.id.localeCompare(b.id); }).forEach(function(node){
          node.y = Math.max(node.y, columnBottom + rowGap);
          columnBottom = node.y + node.height;
        });
      });
      treeNodes.slice().sort(function(a,b){ return b.depth - a.depth; }).forEach(function(parent){
        const children = edges.filter(function(edge){ return edge.fromId === parent.id; })
          .map(function(edge){ return treeNodes.find(function(node){ return node.id === edge.toId; }); })
          .filter(Boolean)
          .sort(function(a,b){ return a.y - b.y; });
        if (children.length < 2) return;
        const centredY = (children[0].y + children[children.length - 1].y + nodeHeight) / 2 - nodeHeight / 2;
        const collides = treeNodes.some(function(other){
          return other.id !== parent.id
            && other.x === parent.x
            && centredY < other.y + other.height
            && centredY + parent.height > other.y;
        });
        if (!collides) parent.y = centredY;
      });
      const localTop = Math.min.apply(null, treeNodes.map(function(node){ return node.y; }));
      const treeOffset = treeTop - localTop;
      treeNodes.forEach(function(node){ node.y += treeOffset; });
      const treeBottom = Math.max.apply(null, treeNodes.map(function(node){ return node.y + node.height; }));
      treeTop = treeBottom + treeGap;
    });

    return {
      nodes: positioned,
      edges: edges,
      columns: columns,
      width: padding * 2 + columnNames.length * nodeWidth + (columnNames.length - 1) * columnGap,
      height: Math.max(520, treeTop - treeGap + padding),
      nodeWidth: nodeWidth,
      nodeHeight: nodeHeight
    };
  },
  render: function(root) {
    const state = root._architectureState;
    if (!state.definition) return;
    const term = root.querySelector("[name=filter]").value;
    const forest = ArchitectureVisualiser.buildDependencyForest(state.definition, term);
    const layout = ArchitectureVisualiser.layoutDependencyForest(forest);
    state.layout = layout;
    const board = root.querySelector("[name=board]");
    board.style.width = layout.width + "px";
    board.style.height = layout.height + "px";
    if (!layout.nodes.length) {
      board.innerHTML = "<div class='av-empty'>No dependency trees match this filter.</div>";
    } else {
      const headers = layout.columns.map(function(column){
        return "<div class='av-column-head' style='left:" + column.x + "px'>" + ArchitectureVisualiser.escape(column.name) + "</div>";
      }).join("");
      board.innerHTML = headers + layout.nodes.map(function(node){
        const item = node.item || {};
        const presentation = ArchitectureVisualiser.getNodePresentation(item, state.definition.AnalysisItems || []);
        const cycle = node.cycle ? " · cycle" : "";
        const classes = "av-node" + (presentation.isInvalid ? " is-invalid" : "") + (presentation.hasPropertyViolation ? " has-property-violation" : "");
        const tooltip = presentation.tooltip || (presentation.hasPropertyViolation ? "Non-model architecture elements must not expose properties." : "");
        return "<button class='" + classes + "' type='button' data-id='" + node.id + "' data-name='" + ArchitectureVisualiser.attr(node.name) + "' title='" + ArchitectureVisualiser.attr(tooltip) + "' aria-label='" + ArchitectureVisualiser.attr(ArchitectureVisualiser.shortName(node.name) + (tooltip ? ". " + tooltip : "")) + "' style='left:" + node.x + "px;top:" + node.y + "px'><span class='av-node-name'>" + ArchitectureVisualiser.escape(ArchitectureVisualiser.shortName(node.name)) + "</span><span class='av-node-meta'>" + ArchitectureVisualiser.escape(presentation.meta + cycle) + "</span></button>";
      }).join("");
    }
    board.querySelectorAll(".av-node").forEach(function(node){ node.addEventListener("click", function(){ ArchitectureVisualiser.selectNode(root, node.dataset.name); }); });
    const relationshipCount = layout.edges.length;
    root.querySelector("[name=summary]").innerHTML =
      "<span class='av-badge'>" + forest.roots.length + " dependency trees</span><span class='av-badge'>" + forest.nodes.length + " non-model items</span><span class='av-badge'>" + relationshipCount + " rendered relationships</span>";
    ArchitectureVisualiser.status(root, "Showing " + layout.nodes.length + " dependency nodes across " + forest.roots.length + " trees in " + state.selected.ProjectName + ".", false);
    requestAnimationFrame(function(){ ArchitectureVisualiser.drawLinks(root); });
  },
  selectNode: function(root, name) {
    const definition = root._architectureState.definition;
    const links = (definition.Links || []).filter(function(link){ return link.FromType === name || link.ToType === name; });
    const related = new Set([name]);
    links.forEach(function(link){ related.add(link.FromType); related.add(link.ToType); });
    root.querySelectorAll(".av-node").forEach(function(node){ node.classList.toggle("is-related", related.has(node.dataset.name)); });
    const item = (definition.Classes || []).concat(definition.Interfaces || []).find(function(found){ return found.Name === name; });
    const presentation = ArchitectureVisualiser.getNodePresentation(item || {}, definition.AnalysisItems || []);
    const details = root.querySelector("[name=details]");
    details.hidden = false;
    root.querySelector("[name=detailName]").textContent = ArchitectureVisualiser.shortName(name);
    const interfaceText = presentation.interfaces.length ? " Implements " + presentation.interfaces.join(", ") + "." : "";
    root.querySelector("[name=detailText]").textContent = name + " — " + (item.StandardElementType || item.Kind || "Architecture item") + ". " + links.length + " mapped relationship" + (links.length === 1 ? "" : "s") + "." + interfaceText + (presentation.tooltip ? " " + presentation.tooltip.replace(/\n/g, " ") : "");
  },
  drawLinks: function(root) {
    const layout = root._architectureState && root._architectureState.layout;
    if (!layout) return;
    const svg = root.querySelector("[name=links]");
    const byId = new Map(layout.nodes.map(function(node){ return [node.id, node]; }));
    svg.setAttribute("width", layout.width);
    svg.setAttribute("height", layout.height);
    svg.setAttribute("viewBox", "0 0 " + layout.width + " " + layout.height);
    svg.innerHTML = layout.edges.map(function(edge){
      const from = byId.get(edge.fromId), to = byId.get(edge.toId);
      if (!from || !to) return "";
      const x1 = from.x + from.width, y1 = from.y + from.height / 2;
      const x2 = to.x, y2 = to.y + to.height / 2;
      const bend = x1 + (x2 - x1) / 2;
      return "<path d='M " + x1 + " " + y1 + " C " + bend + " " + y1 + ", " + bend + " " + y2 + ", " + x2 + " " + y2 + "' />";
    }).join("");
  },
  status: function(root, message, error) { const status = root.querySelector("[name=status]"); status.textContent = message; status.classList.toggle("is-error", !!error); },
  shortName: function(name) { const parts = String(name || "").split("."); return parts[parts.length - 1] || name; },
  escape: function(value) { const node = document.createElement("span"); node.textContent = value == null ? "" : String(value); return node.innerHTML; },
  attr: function(value) { return ArchitectureVisualiser.escape(value).replace(/'/g, "&#39;"); }
};
